type Linha = Record<string, unknown>;
const tarefa: Linha = { id: 1, titulo: 'Revisar PR', notas: 'texto longo', projetoId: 7 };
const projeto: Linha = { id: 7, nome: 'Cockpit' };

function buscar(args: { select?: Record<string, boolean>; include?: { projeto: boolean } }): Linha {
  if (args.select) {
    return Object.fromEntries(Object.keys(args.select).map((c) => [c, tarefa[c]]));
  }
  return args.include?.projeto ? { ...tarefa, projeto } : { ...tarefa };
}

