type Migration = { nome: string; sql: string };
const soma = (s: string) => [...s].reduce((a, c) => (a + c.charCodeAt(0)) % 9973, 0);
const aplicadas = new Map<string, number>();

function deploy(pasta: Migration[]) {
  for (const m of pasta) {
    const antes = aplicadas.get(m.nome);
    if (antes === undefined) {
      aplicadas.set(m.nome, soma(m.sql));
      console.log('aplica', m.nome);
    } else if (antes !== soma(m.sql)) {
      console.log('ERRO: migration aplicada foi editada:', m.nome);
      return;
    }
  }
  console.log('ok,', aplicadas.size, 'aplicadas');
}

