type Contas = { ana: number; beto: number };
let banco: Contas = { ana: 100, beto: 50 };

function transfere(db: Contas, valor: number) {
  db.beto += valor;
  if (db.ana < valor) throw new Error('saldo insuficiente');
  db.ana -= valor;
}

function transacao(trabalho: (tx: Contas) => void) {
  const tx = { ...banco };
  try {
    trabalho(tx);
    banco = tx;
    console.log('commit');
  } catch (e) {
    console.log('rollback:', (e as Error).message);
  }
}

try {
  transfere(banco, 150);
} catch {
  console.log('erro no meio, sem transação');
}
console.log(banco);

banco = { ana: 100, beto: 50 };
transacao((tx) => transfere(tx, 150));
console.log(banco);
