const espera = (ms: number) => new Promise((r) => setTimeout(r, ms));
const linha = { estoque: 10, versao: 1 };

function atualiza(novo: number, versaoLida: number): number {
  if (linha.versao !== versaoLida) return 0; // where versao = :lida
  linha.estoque = novo;
  linha.versao++;
  return 1; // linhas afetadas
}

