const linhas = Array.from({ length: 100_000 }, (_, i) => i * 2);

function seqScan(alvo: number): number {
  let lidas = 0;
  for (const v of linhas) {
    lidas++;
    if (v === alvo) break;
  }
  return lidas;
}

function btree(alvo: number): number {
  let lo = 0, hi = linhas.length - 1, passos = 0;
  while (lo <= hi) {
    passos++;
    const meio = (lo + hi) >> 1;
    const v = linhas[meio]!;
    if (v === alvo) break;
    if (v < alvo) lo = meio + 1;
    else hi = meio - 1;
  }
  return passos;
}

console.log(seqScan(150_000), btree(150_000));
console.log(seqScan(7), btree(7));

