class Consulta {
  private filtros: string[] = [];
  private valores: unknown[] = [];
  private tabela: string;
  constructor(tabela: string) {
    this.tabela = tabela;
  }
  where(coluna: string, valor: unknown) {
    this.valores.push(valor);
    this.filtros.push(`${coluna} = $${this.valores.length}`);
    return this;
  }
  toSQL() {
    const onde = this.filtros.length ? ' where ' + this.filtros.join(' and ') : '';
    return { sql: `select * from ${this.tabela}${onde}`, bindings: this.valores };
  }
}

