const tabela: string[] = [];

class Conexao {
  private pendente: string[] = [];
  execute(linha: string, opcoes: { autoCommit?: boolean } = {}) {
    this.pendente.push(linha);
    if (opcoes.autoCommit) this.commit();
  }
  commit() {
    tabela.push(...this.pendente);
    this.pendente = [];
  }
  close() {
    this.pendente = []; // rollback do que ficou pendente
  }
}

