let agora = 0;
const chaves = new Map<string, { valor: string; expira: number }>();

function setNx(chave: string, valor: string, ttl: number): boolean {
  const atual = chaves.get(chave);
  if (atual && atual.expira > agora) return false;
  chaves.set(chave, { valor, expira: agora + ttl });
  return true;
}

function solta(chave: string, token: string): boolean {
  if (chaves.get(chave)?.valor !== token) return false;
  return chaves.delete(chave);
}

