let agora = 0;
let idasAoBanco = 0;
const cache = new Map<string, { valor: number; expira: number }>();

function totalDoDia(dia: string): number {
  const c = cache.get(dia);
  if (c && c.expira > agora) return c.valor;
  idasAoBanco++;
  const valor = 100 + idasAoBanco; // a "consulta cara"; o dado muda a cada ida
  cache.set(dia, { valor, expira: agora + 60 });
  return valor;
}

